-- operations: int_spine_operations_measures pivoted to one row per spine key (design: p3c/design.md section 2).

with

spine as (
    select
        hospital.spine_key,
        (hospital.window_start::timestamp) at time zone 'UTC' as event_timestamp
    from {{ ref('int_hospital_spine') }} as hospital
),

measures as (
    select
        measures.spine_key,
        measures.value_number,
        measures.value_text,
        measures.measure_source || '|' || measures.measure_control || '|' || measures.field as pivot_key
    from {{ ref('int_spine_operations_measures') }} as measures
),

pivoted as (
    select
        spine_key,
        max(value_number) filter (where pivot_key = 'hhs_capacity|C260|value') as c260__value__number,
        max(value_number) filter (where pivot_key = 'hhs_capacity|C261|value') as c261__value__number,
